+static guint besl_to_us(guint8 besl)
+{
+    unsigned int us;
+    if (besl == 0) {
+        us = 125;
+    } else if (besl == 1) {
+        us = 150;
+    } else if (besl <= 5) {
+        us = 100 * besl;
+    } else {
+        us = 1000 * (besl - 5);
+    }
+    return us;
+}
