+
+        if (data->transaction_state != STATE_SUBPID_INVALID)
+        {
+            DISSECTOR_ASSERT(data->prev != NULL);
+            DISSECTOR_ASSERT(data->prev->transaction != NULL);
+            data->transaction = data->prev->transaction;
+        }
+    }
